"use client";

import React, { useState, useMemo } from "react";
import { 
  Calendar, MapPin, Filter, ChevronDown, 
  Layers, Globe, CheckCircle2, Sparkles 
} from "lucide-react";

/* --- 1. ROBUST DATASET --- */
const HOLIDAYS_DB = [
  // --- 2025 ---
  { id: 1, name: "New Year's Day", date: "Jan 01", day: "Wednesday", year: "2025", type: "Public", region: "Global" },
  { id: 2, name: "Republic Day", date: "Jan 26", day: "Sunday", year: "2025", type: "National", region: "India" },
  { id: 3, name: "Holi", date: "Mar 14", day: "Friday", year: "2025", type: "Optional", region: "North India" },
  { id: 4, name: "Good Friday", date: "Apr 18", day: "Friday", year: "2025", type: "Public", region: "Global" },
  { id: 5, name: "Independence Day", date: "Aug 15", day: "Friday", year: "2025", type: "National", region: "India" },
  { id: 6, name: "Diwali", date: "Oct 20", day: "Monday", year: "2025", type: "Public", region: "India" },

  // --- 2026 ---
  { id: 7, name: "New Year's Day", date: "Jan 01", day: "Thursday", year: "2026", type: "Public", region: "Global" },
  { id: 8, name: "Republic Day", date: "Jan 26", day: "Monday", year: "2026", type: "National", region: "India" },
  { id: 9, name: "Ugadi", date: "Mar 19", day: "Thursday", year: "2026", type: "Optional", region: "Telangana" },
  { id: 10, name: "Good Friday", date: "Apr 03", day: "Friday", year: "2026", type: "Public", region: "Global" },
  { id: 11, name: "May Day", date: "May 01", day: "Friday", year: "2026", type: "Public", region: "Global" },
  { id: 12, name: "Kannada Rajyotsava", date: "Nov 01", day: "Sunday", year: "2026", type: "Optional", region: "Karnataka" },
  { id: 13, name: "Christmas", date: "Dec 25", day: "Friday", year: "2026", type: "Public", region: "Global" },
];

export default function PremiumHolidayList() {
  // --- STATE ---
  const [yearFilter, setYearFilter] = useState("2026");
  const [typeFilter, setTypeFilter] = useState("All");
  const [locFilter, setLocFilter] = useState("All");

  // --- SMART FILTER LOGIC ---
  const filteredData = useMemo(() => {
    return HOLIDAYS_DB.filter((h) => {
      // 1. Year Match
      const matchYear = h.year === yearFilter;
      
      // 2. Type Match (Public includes National)
      const matchType = typeFilter === "All" || h.type === typeFilter || (typeFilter === 'Public' && h.type === 'National');

      // 3. Location Match (Show Global + National + Specific State)
      const matchLoc = 
        locFilter === "All" || 
        h.region === locFilter || 
        h.region === "Global" || 
        (h.region === "India" && locFilter !== "Global"); // Show India holidays even if state is selected

      return matchYear && matchType && matchLoc;
    });
  }, [yearFilter, typeFilter, locFilter]);

  return (
    <div className="min-h-screen bg-[#F3F5F8] dark:bg-[#020408] p-6 lg:p-12 font-sans text-slate-900 dark:text-slate-100">
      <div className="mx-auto max-w-5xl space-y-8">
        
        {/* --- 1. HEADER & METRICS --- */}
        <div className="flex flex-col md:flex-row justify-between items-end border-b border-slate-200 dark:border-slate-800 pb-8 gap-6">
          <div className="space-y-2">
            <h1 className="text-4xl font-black tracking-tighter uppercase italic text-slate-900 dark:text-white">
              Holiday <span className="text-slate-400">Schedule</span>
            </h1>
            <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">
              Official Organizational Calendar • {yearFilter}
            </p>
          </div>
          
          {/* Quick Stats */}
          <div className="flex gap-4">
             <StatBadge label="Total" value={filteredData.length} />
             <StatBadge label="Public" value={filteredData.filter(h => h.type !== 'Optional').length} color="text-emerald-500" />
             <StatBadge label="Optional" value={filteredData.filter(h => h.type === 'Optional').length} color="text-amber-500" />
          </div>
        </div>

        {/* --- 2. THE CONTROL STRIP (FILTERS) --- */}
        <div className="bg-white dark:bg-slate-900 p-2 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col md:flex-row gap-2">
          
          {/* Year Filter */}
          <div className="relative flex-1">
             <div className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400"><Calendar size={14} /></div>
             <select 
               value={yearFilter}
               onChange={(e) => setYearFilter(e.target.value)}
               className="w-full bg-slate-50 dark:bg-slate-950 appearance-none rounded-xl py-3 pl-10 pr-4 text-xs font-black uppercase tracking-widest outline-none focus:ring-2 focus:ring-brand-500 transition-all cursor-pointer hover:bg-slate-100 dark:hover:bg-slate-800"
             >
               <option value="2025">Fiscal Year 2025</option>
               <option value="2026">Fiscal Year 2026</option>
             </select>
             <ChevronDown size={14} className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" />
          </div>

          {/* Location Filter */}
          <div className="relative flex-1">
             <div className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400"><MapPin size={14} /></div>
             <select 
               value={locFilter}
               onChange={(e) => setLocFilter(e.target.value)}
               className="w-full bg-slate-50 dark:bg-slate-950 appearance-none rounded-xl py-3 pl-10 pr-4 text-xs font-black uppercase tracking-widest outline-none focus:ring-2 focus:ring-brand-500 transition-all cursor-pointer hover:bg-slate-100 dark:hover:bg-slate-800"
             >
               <option value="All">All Locations</option>
               <option value="Global">Global / Remote</option>
               <option value="Telangana">Hyderabad (Telangana)</option>
               <option value="Karnataka">Bangalore (Karnataka)</option>
               <option value="North India">Delhi / NCR</option>
             </select>
             <ChevronDown size={14} className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" />
          </div>

          {/* Type Filter (Visual Toggle) */}
          <div className="flex bg-slate-50 dark:bg-slate-950 p-1 rounded-xl">
             {['All', 'Public', 'Optional'].map(type => (
               <button
                 key={type}
                 onClick={() => setTypeFilter(type)}
                 className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${
                   typeFilter === type 
                   ? "bg-white dark:bg-slate-800 shadow-md text-slate-900 dark:text-white scale-100" 
                   : "text-slate-400 hover:text-slate-600 dark:hover:text-slate-300"
                 }`}
               >
                 {type}
               </button>
             ))}
          </div>
        </div>

        {/* --- 3. THE DATA GRID --- */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {filteredData.length > 0 ? (
            filteredData.map((holiday) => (
              <div 
                key={holiday.id}
                className="group relative bg-white dark:bg-slate-900 p-6 rounded-[1.5rem] border border-slate-200 dark:border-slate-800 hover:border-brand-500/50 transition-all hover:shadow-xl hover:shadow-brand-500/5 overflow-hidden"
              >
                {/* Visual Flair */}
                <div className="absolute top-0 right-0 p-6 opacity-10 group-hover:opacity-20 transition-opacity">
                   {holiday.type === 'Optional' ? <Sparkles size={40} /> : <Globe size={40} />}
                </div>

                <div className="flex items-start gap-5 relative z-10">
                   {/* Date Block */}
                   <div className="flex flex-col items-center justify-center w-16 h-16 bg-slate-50 dark:bg-slate-800 rounded-2xl border border-slate-100 dark:border-slate-700">
                      <span className="text-[9px] font-black uppercase text-slate-400">{holiday.date.split(' ')[0]}</span>
                      <span className="text-xl font-black text-slate-900 dark:text-white leading-none mt-1">{holiday.date.split(' ')[1]}</span>
                   </div>

                   {/* Info */}
                   <div className="flex-1">
                      <div className="flex items-center gap-2 mb-1.5">
                         <TypeBadge type={holiday.type} />
                         <span className="text-[9px] font-bold text-slate-400 uppercase flex items-center gap-1">
                            <MapPin size={10} /> {holiday.region}
                         </span>
                      </div>
                      <h3 className="text-lg font-black tracking-tight text-slate-900 dark:text-white uppercase">
                        {holiday.name}
                      </h3>
                      <p className="text-xs font-bold text-slate-400 mt-1 uppercase tracking-widest group-hover:text-brand-600 transition-colors">
                        {holiday.day}
                      </p>
                   </div>
                </div>
              </div>
            ))
          ) : (
            <div className="col-span-full py-16 text-center border-2 border-dashed border-slate-200 dark:border-slate-800 rounded-[2rem]">
               <Filter size={32} className="mx-auto text-slate-300 mb-4" />
               <p className="text-xs font-black uppercase text-slate-400 tracking-widest">No holidays match filters</p>
            </div>
          )}
        </div>

      </div>
    </div>
  );
}

/* --- MICRO COMPONENTS --- */

const StatBadge = ({ label, value, color = "text-slate-900 dark:text-white" }: any) => (
  <div className="bg-white dark:bg-slate-900 px-5 py-3 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm text-center min-w-[80px]">
    <div className={`text-xl font-black leading-none ${color}`}>{value}</div>
    <div className="text-[9px] font-black text-slate-400 uppercase tracking-widest mt-1">{label}</div>
  </div>
);

const TypeBadge = ({ type }: { type: string }) => {
  const isOptional = type === "Optional";
  return (
    <span className={`flex items-center gap-1 px-2 py-0.5 rounded-md text-[9px] font-black uppercase tracking-widest ${
      isOptional 
      ? "bg-amber-100 text-amber-600 border border-amber-200 dark:bg-amber-500/10 dark:text-amber-500 dark:border-amber-500/20" 
      : "bg-emerald-100 text-emerald-600 border border-emerald-200 dark:bg-emerald-500/10 dark:text-emerald-500 dark:border-emerald-500/20"
    }`}>
      {isOptional ? <Sparkles size={8} /> : <CheckCircle2 size={8} />}
      {type}
    </span>
  );
};